 17	use chrono::Utc;
 18	use serde_json::json;
 19	use tempfile::TempDir;
 20	use uuid::Uuid;
 21	
 22	#[derive(Clone, Copy)]
 23	struct TestScorer;
 24	
 25	impl FunderScorer for TestScorer {
 26	    async fn score(&self, input: &ScoringInput) -> Result<ScoredPairs, EntityIngestionError> {
 27	        let pairs = input
 28	            .rows
 29	            .iter()
 30	            .enumerate()
 31	            .flat_map(|(index, left)| {
 32	                input.rows[index + 1..].iter().map(move |right| {
 33	                    let (left, right) = if left.key < right.key {
 34	                        (left, right)
 35	                    } else {
 36	                        (right, left)
 37	                    };
 38	                    ScoredPair {
 39	                        left: left.key.clone(),
 40	                        right: right.key.clone(),
 41	                        probability: 0.5,
 42	                        name_level: 0,
 43	                        address_level: -1,
 44	                    }
 45	                })
 46	            })
 47	            .collect();
 48	        ScoredPairs::checked(pairs, json!({"calibrated": false}), input)
 49	    }
 50	}
 51	
 52	async fn resolved_test_run() -> anyhow::Result<(TempDir, DeclarationLoad)> {
 53	    let temporary = tempfile::tempdir()?;
 54	    let key = IngestionKey::default();
 55	    let root = temporary.path().join("data");
 56	    let storage = ExposedDataPipeline::new_with_ingestion_key(&root, key)?;
 57	    let member = MemberAsId::new(Uuid::from_u128(1), 4613)?;
 58	    let fetched_at = Utc::now();
 59	    let declarations = [
 60	        json!({
 61	            "id": 1,
 62	            "category": {"id": 3, "name": "Donations"},
 63	            "versions": [{"register": {"id": 820, "publishedDate": "2026-09-07"}, "fields": [
 64	                {"name": "PayerName", "value": "Parent payer"},
 65	                {"name": "Value", "value": "20"}
 66	            ]}]
 67	        }),
 68	        json!({
 69	            "id": 2,
 70	            "parentInterestId": 1,
 71	            "category": {"id": 3, "name": "Donations"},
 72	            "versions": [{"register": {"id": 820, "publishedDate": "2026-09-07"}, "fields": [
 73	                {"name": "UltimatePayerName", "value": "Explicit ultimate payer"},
 74	                {"name": "DonorName", "value": "Child donor"},
 75	                {"name": "Value", "value": "30"}
 76	            ]}]
 77	        }),
 78	        json!({
 79	            "id": 3,
 80	            "category": {"id": 3, "name": "Donations"},
 81	            "versions": [{"register": {"id": 820, "publishedDate": "2026-09-07"}, "fields": [
 82	                {"name": "DonorName", "value": "Shared funder"},
 83	                {"name": "DonorStatus", "value": "Unincorporated association"},
 84	                {"name": "Value", "value": "40"}
 85	            ]}]
 86	        }),
 87	        json!({
 88	            "id": 4,
 89	            "category": {"id": 3, "name": "Donations"},
 90	            "versions": [{"register": {"id": 820, "publishedDate": "2026-09-07"}, "fields": [
 91	                {"name": "DonorName", "value": "Shared funder"},
 92	                {"name": "DonorStatus", "value": "Company"},
 93	                {"name": "DonorCompanyIdentifier", "value": "12345678"},
 94	                {"name": "Value", "value": "50"}
 95	            ]}]
 96	        }),
 97	    ]
 98	    .into_iter()
 99	    .map(|source| {
100	        super::super::declaration_source::replay_declaration(source, fetched_at)
101	            .map(|evidence| evidence.declaration().clone())
102	    })
103	    .collect::<Result<Vec<CapturedDeclaration>, _>>()?;
104	    storage
105	        .write_raw_declarations(member, &declarations)
106	        .await?;
107	    DeclarationCleanerService::new(storage.clone())
108	        .clean_declarations()
109	        .await?;
110	    DeclarationResolverService::new(storage.clone(), TestScorer, 100)
111	        .resolve_declarations()
112	        .await?;
113	    let load = storage.read_declaration_load().await?;
114	    Ok((temporary, load))
115	}
116	
117	#[tokio::test]
118	async fn explicit_ultimate_payer_on_child_declaration_is_loadable() -> anyhow::Result<()> {
119	    let (_temporary, load) = resolved_test_run().await?;
120	    let child_attribution = load
121	        .funding_entries
122	        .iter()
123	        .find(|entry| entry.attribution_basis.as_deref() == Some("explicit_ultimate_payer"))
124	        .expect("the child payment selects its explicit ultimate payer");
125	
126	    assert_eq!(child_attribution.source_declaration_id, 2);
127	    assert_eq!(child_attribution.selected_parent_declaration_id, None);
128	    Ok(())
129	}
130	
131	#[tokio::test]
132	async fn company_number_uses_the_matching_company_kind() -> anyhow::Result<()> {
133	    let (_temporary, load) = resolved_test_run().await?;
134	    let company = load
135	        .funders
136	        .iter()
137	        .find(|funder| funder.company_number.as_deref() == Some("12345678"))
138	        .expect("the resolved identity retains its reported company number");
139	
140	    assert_eq!(company.kind.as_deref(), Some("Company"));
141	    Ok(())
142	}

